using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.Infrastructure; using Microsoft.AspNetCore.Mvc.ModelBinding; namespace ApiFromLecture.Exceptions; public class CustomProblemDetailsFactory:ProblemDetailsFactory{public override ProblemDetails CreateProblemDetails(HttpContext h,int? statusCode=null,string? title=null,string? type=null,string? detail=null,string? instance=null){var p=new ProblemDetails{Status=statusCode??500,Title=title,Type=type,Detail=detail,Instance=instance};Enrich(p,h);return p;} public override ValidationProblemDetails CreateValidationProblemDetails(HttpContext h,ModelStateDictionary m,int? statusCode=null,string? title=null,string? type=null,string? detail=null,string? instance=null){var p=new ValidationProblemDetails(m){Status=statusCode??400,Title=title??"Validation failed",Type=type,Detail=detail,Instance=instance};Enrich(p,h);return p;} static void Enrich(ProblemDetails p,HttpContext h){p.Extensions["traceId"]=h.TraceIdentifier;p.Extensions["timestamp"]=DateTime.UtcNow;}}
